package com.hrx.recovery;
import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.server.LocalServerPort;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.*;
import static org.junit.jupiter.api.Assertions.*;import static com.hrx.recovery.TestSupport.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
@EnabledIfEnvironmentVariable(named="HRX_TEST_DB_URL",matches="jdbc:postgresql:.*hrx_test_.*")
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class DeliveryIntegrationTest {
 @LocalServerPort int port;@Autowired JdbcTemplate runtime;
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){properties(r);}
 @BeforeAll void prepare(){fixtures();for(int n=1;n<=4;n++)for(String a:List.of("read","create","update","verify"))grant(admin(),n,"project_delivery",a);grant(admin(),6,"project_delivery","read");}
 Map<String,Object> plan(){return Map.of("projectId",PROJECT.toString(),"title","TEST milestone "+keyId(),"plannedDate",today().minusDays(1).toString(),"responsibleUserId",user(2).toString());}
 String create(int actor,Map<String,Object> body,String key,int code) throws Exception{var r=request(port,actor,"/project-delivery/milestones",body,key);assertEquals(code,r.statusCode(),r.body());return JSON.readTree(r.body()).path("milestone_id").asText();}
 Map<String,Object> change(int rev,String code){return new HashMap<>(Map.of("expectedRevision",rev,"eventCode",code,"note","TEST milestone "+code,"evidenceRefs",List.of("hrx-file:test/project")));}
 void append(int actor,String id,Map<String,Object> body,int code) throws Exception{var r=request(port,actor,"/project-delivery/milestones/"+id+"/events",body,keyId());assertEquals(code,r.statusCode(),r.body());}
 @Test void responsibleSubmissionIndependentReviewReturnAndDateHistory() throws Exception{
  String key=keyId();var b=plan();String id=create(1,b,key,200);assertEquals(id,create(1,b,key,200));var altered=new HashMap<>(b);altered.put("title","TEST altered milestone");create(1,altered,key,409);append(1,id,change(0,"START"),403);append(2,id,change(0,"SUBMIT"),422);append(2,id,change(0,"START"),200);append(1,id,change(1,"NOTE"),200);var reschedule=change(2,"RESCHEDULE");reschedule.put("plannedDate",today().plusDays(3).toString());append(2,id,reschedule,200);
  var missing=change(3,"SUBMIT");missing.put("evidenceRefs",List.of());append(2,id,missing,422);append(2,id,change(3,"SUBMIT"),200);append(1,id,change(4,"CONFIRM"),403);append(2,id,change(4,"CONFIRM"),403);append(2,id,change(4,"RESCHEDULE"),422);append(3,id,change(4,"RETURN"),200);append(2,id,change(5,"SUBMIT"),200);append(3,id,change(6,"CONFIRM"),200);append(1,id,change(7,"NOTE"),422);
  var m=JSON.readTree(request(port,6,"/project-delivery/milestones/"+id,null,null).body());assertEquals("CONFIRMED",m.get("current_status").asText());assertFalse(m.get("overdue").asBoolean());assertEquals(7,m.get("revision").asInt());assertEquals(user(3).toString(),m.get("confirmed_by").asText());var events=JSON.readTree(request(port,1,"/project-delivery/milestones/"+id+"/events",null,null).body());assertEquals(7,events.size());assertEquals(today().minusDays(1).toString(),events.get(2).get("previous_planned_date").asText());assertEquals(today().plusDays(3).toString(),events.get(2).get("planned_date").asText());assertEquals(8,admin().queryForObject("SELECT count(*) FROM hrx.audit_event WHERE resource_id=?::uuid",Integer.class,id));
 }
 @Test void scopeRevocationAssignmentAndNoDirectWrites() throws Exception{
  String id=create(1,plan(),keyId(),200);var wrong=new HashMap<>(plan());wrong.put("responsibleUserId",user(5).toString());create(1,wrong,keyId(),403);create(5,plan(),keyId(),403);wrong.put("projectId",OTHER.toString());create(1,wrong,keyId(),403);assertEquals(404,request(port,5,"/project-delivery/milestones/"+id,null,null).statusCode());assertEquals(0,JSON.readTree(request(port,5,"/project-delivery/milestones",null,null).body()).get("total").asInt());assertEquals(400,request(port,1,"/project-delivery/milestones?state=INVALID",null,null).statusCode());append(6,id,change(0,"START"),403);
  admin().update("UPDATE hrx.capability_grant SET enabled=false WHERE user_id=? AND project_id=? AND resource_type='project_delivery' AND action_code='update'",user(2),PROJECT);try{append(2,id,change(0,"START"),403);}finally{admin().update("UPDATE hrx.capability_grant SET enabled=true WHERE user_id=? AND project_id=? AND resource_type='project_delivery' AND action_code='update'",user(2),PROJECT);}
  admin().update("UPDATE hrx.capability_grant SET enabled=false WHERE user_id=? AND project_id=? AND resource_type='project_delivery' AND action_code='read'",user(1),PROJECT);try{assertEquals(404,request(port,1,"/project-delivery/milestones/"+id,null,null).statusCode());}finally{admin().update("UPDATE hrx.capability_grant SET enabled=true WHERE user_id=? AND project_id=? AND resource_type='project_delivery' AND action_code='read'",user(1),PROJECT);}
  assertThrows(org.springframework.dao.DataAccessException.class,()->runtime.update("UPDATE hrx.delivery_milestone SET current_status='CONFIRMED'"));assertThrows(org.springframework.dao.DataAccessException.class,()->runtime.update("DELETE FROM hrx.delivery_milestone_event"));assertTrue(runtime.queryForList("SELECT * FROM hrx.delivery_milestone").isEmpty());
 }
 @Test void projectOnlyIdentityDoesNotInheritProcurementScope() throws Exception{
  var j=admin();UUID p=UUID.randomUUID();j.update("INSERT INTO hrx.user_account(user_id,idp_subject,display_name,active) VALUES (?,'TEST-7','TEST project-only employee',true) ON CONFLICT DO NOTHING",user(7));j.update("INSERT INTO hrx.business_project(project_id,project_code,project_name,org_unit_code) VALUES (?,?,'TEST project-only','TEST')",p,"TEST DELIVERY "+keyId());for(String a:List.of("read","create","update","verify"))j.update("INSERT INTO hrx.capability_grant(user_id,project_id,resource_type,action_code,enabled,approved_by,approved_at) VALUES (?,?,'project_delivery',?,true,?,now())",user(7),p,a,user(5));var b=new HashMap<>(plan());b.put("projectId",p.toString());b.put("responsibleUserId",user(7).toString());String id=create(7,b,keyId(),200);assertEquals(200,request(port,7,"/project-delivery/milestones/"+id,null,null).statusCode());assertEquals(0,JSON.readTree(request(port,7,"/supply-chain/projects",null,null).body()).size());assertEquals(0,JSON.readTree(request(port,7,"/supply-chain/readiness",null,null).body()).get("total").asInt());assertEquals(0,JSON.readTree(request(port,7,"/supply-chain/demands",null,null).body()).get("total").asInt());assertEquals(404,request(port,1,"/project-delivery/milestones/"+id,null,null).statusCode());
 }
 @Test void cancellationAndConcurrentTransitionsKeepOneHistory() throws Exception{
  String id=create(1,plan(),keyId(),200);append(2,id,change(0,"CANCEL"),403);append(1,id,change(0,"CANCEL"),200);append(2,id,change(1,"START"),422);String second=create(1,plan(),keyId(),200);var pool=Executors.newFixedThreadPool(2);try{Callable<Integer> start=()->request(port,2,"/project-delivery/milestones/"+second+"/events",change(0,"START"),keyId()).statusCode();var a=pool.submit(start);var b=pool.submit(start);assertEquals(Set.of(200,409),new HashSet<>(List.of(a.get(15,TimeUnit.SECONDS),b.get(15,TimeUnit.SECONDS))));}finally{pool.shutdownNow();}
  String key=keyId();var body=change(1,"NOTE");var r=request(port,2,"/project-delivery/milestones/"+second+"/events",body,key);assertEquals(200,r.statusCode(),r.body());var replay=request(port,2,"/project-delivery/milestones/"+second+"/events",body,key);assertEquals(200,replay.statusCode(),replay.body());assertEquals(JSON.readTree(r.body()),JSON.readTree(replay.body()));
 }
 @Test @EnabledIfEnvironmentVariable(named="HRX_BROWSER",matches="true") void browserDeliveryMilestones() throws Exception{BrowserRunner.run(port,"delivery.mjs",Map.of("user1",token(1),"user2",token(2),"user3",token(3),"user6",token(6)),Map.of());}
 Map<String,Object> dependent(String title,String... ids){var b=new HashMap<>(plan());b.put("title",title);b.put("predecessorIds",List.of(ids));return b;}
 void confirm(String id) throws Exception{append(2,id,change(0,"START"),200);append(2,id,change(1,"SUBMIT"),200);append(3,id,change(2,"CONFIRM"),200);}
 @Test void prerequisitesBlockStartAndCancellationUntilIndependentlyConfirmed() throws Exception{
  String a=create(1,plan(),keyId(),200),b=create(1,plan(),keyId(),200),title="TEST child dependency "+keyId(),key=keyId();var body=dependent(title,a,b);String child=create(1,body,key,200);assertEquals(child,create(1,body,key,200));append(2,child,change(0,"START"),409);append(1,a,change(0,"CANCEL"),409);var before=JSON.readTree(request(port,6,"/project-delivery/milestones/"+child,null,null).body());assertTrue(before.get("blocked").asBoolean());assertEquals(2,before.get("unconfirmed_predecessors").asInt());assertEquals(2,JSON.readTree(request(port,6,"/project-delivery/milestones/"+child+"/dependencies",null,null).body()).get("predecessors").size());
  confirm(a);append(2,child,change(0,"START"),409);confirm(b);var ready=JSON.readTree(request(port,1,"/project-delivery/milestones/"+child,null,null).body());assertFalse(ready.get("blocked").asBoolean());assertEquals(0,ready.get("unconfirmed_predecessors").asInt());append(2,child,change(0,"START"),200);assertEquals(0,JSON.readTree(request(port,1,"/project-delivery/milestones?state=BLOCKED&q="+title.replace(" ","%20"),null,null).body()).get("total").asInt());assertEquals(404,request(port,5,"/project-delivery/milestones/"+child+"/dependencies",null,null).statusCode());
  String parent=create(1,plan(),keyId(),200),cancelledChild=create(1,dependent("TEST cancel child "+keyId(),parent),keyId(),200);append(1,cancelledChild,change(0,"CANCEL"),200);append(1,parent,change(0,"CANCEL"),200);assertThrows(org.springframework.dao.DataAccessException.class,()->runtime.update("DELETE FROM hrx.milestone_dependency"));assertTrue(runtime.queryForList("SELECT * FROM hrx.milestone_dependency").isEmpty());
 }
 @Test void invalidDependenciesRollbackTheNewMilestoneAndNeverChangeExistingEdges() throws Exception{
  String parent=create(1,plan(),keyId(),200),title="TEST invalid child "+keyId();create(1,dependent(title,parent,parent),keyId(),422);create(1,dependent(title,parent,UUID.randomUUID().toString()),keyId(),403);String cancelled=create(1,plan(),keyId(),200);append(1,cancelled,change(0,"CANCEL"),200);create(1,dependent(title,cancelled),keyId(),409);assertEquals(0,admin().queryForObject("SELECT count(*) FROM hrx.delivery_milestone WHERE title=?",Integer.class,title));
  UUID project=UUID.randomUUID();admin().update("INSERT INTO hrx.business_project(project_id,project_code,project_name,org_unit_code) VALUES (?,?,'TEST dependency cross-project','TEST')",project,"TEST DEP "+keyId());for(int n=1;n<=2;n++)admin().update("INSERT INTO hrx.capability_grant(user_id,project_id,resource_type,action_code,enabled,approved_by,approved_at) SELECT user_id,?,resource_type,action_code,true,approved_by,approved_at FROM hrx.capability_grant WHERE user_id=? AND project_id=? AND resource_type='project_delivery'",project,user(n),PROJECT);var otherBody=new HashMap<>(plan());otherBody.put("projectId",project.toString());String other=create(1,otherBody,keyId(),200);create(1,dependent(title,other),keyId(),403);assertEquals(0,admin().queryForObject("SELECT count(*) FROM hrx.delivery_milestone WHERE title=?",Integer.class,title));
  var tooMany=dependent(title);tooMany.put("predecessorIds",java.util.stream.IntStream.range(0,31).mapToObj(n->UUID.randomUUID().toString()).toList());create(1,tooMany,keyId(),400);
 }
 @Test void concurrentPredecessorCancellationAndChildCreationAreSerialized() throws Exception{
  var pool=Executors.newFixedThreadPool(2);try{for(int n=0;n<4;n++){String parent=create(1,plan(),keyId(),200),title="TEST concurrent child "+keyId();var latch=new CountDownLatch(1);var a=pool.submit(()->{latch.await();return request(port,1,"/project-delivery/milestones",dependent(title,parent),keyId());});var b=pool.submit(()->{latch.await();return request(port,1,"/project-delivery/milestones/"+parent+"/events",change(0,"CANCEL"),keyId());});latch.countDown();var made=a.get(15,TimeUnit.SECONDS);var cancelled=b.get(15,TimeUnit.SECONDS);assertEquals(Set.of(200,409),new HashSet<>(List.of(made.statusCode(),cancelled.statusCode())),made.body()+cancelled.body());if(made.statusCode()==200){assertEquals("PLANNED",admin().queryForObject("SELECT current_status FROM hrx.delivery_milestone WHERE milestone_id=?::uuid",String.class,parent));}else assertEquals(0,admin().queryForObject("SELECT count(*) FROM hrx.delivery_milestone WHERE title=?",Integer.class,title));}}finally{pool.shutdownNow();}
 }
 @Test void legacyCreateIdempotencyFingerprintRemainsReplayable() throws Exception{
  var b=plan();String id=create(1,b,keyId(),200),key=keyId();var ordered=new LinkedHashMap<String,Object>();for(String name:List.of("projectId","title","plannedDate","responsibleUserId"))ordered.put(name,b.get(name));String hash=FileService.hash(JSON.writeValueAsBytes(ordered));admin().update("INSERT INTO hrx.api_idempotency(actor_user_id,operation,idempotency_key,request_hash,response_body) VALUES (?,'milestone.create',?,?,?::jsonb)",user(1),key,hash,JSON.writeValueAsString(Map.of("milestone_id",id,"revision",0)));assertEquals(id,create(1,b,key,200));var explicit=new HashMap<>(b);explicit.put("predecessorIds",List.of());assertEquals(id,create(1,explicit,key,200));explicit.put("predecessorIds",List.of(id));create(1,explicit,key,409);
 }
 @Test @EnabledIfEnvironmentVariable(named="HRX_BROWSER",matches="true") void browserMilestoneDependencies() throws Exception{
  String a=create(1,plan(),keyId(),200),title=admin().queryForObject("SELECT title FROM hrx.delivery_milestone WHERE milestone_id=?::uuid",String.class,a);BrowserRunner.run(port,"dependencies.mjs",Map.of("user1",token(1),"user2",token(2),"user3",token(3)),Map.of("HRX_E2E_PARENT",title));
 }

}
